// ================================
// 0) Texto del correo (snippet)
// ================================
const text = ($json.snippet || "").toString();
const textU = text.toUpperCase();

// ================================
// Helpers
// ================================
function cleanForSheets(value) {
  let s = (value ?? "").toString()
    .normalize("NFKD")
    .replace(/[\u200B-\u200D\uFEFF]/g, "")
    .trim();

  // Quita "=" al inicio (anti-fórmulas en Sheets)
  s = s.replace(/^=\s*/g, "");

  if (!s) s = "NO SE";
  return s;
}

const pad = (n) => String(n).padStart(2, "0");

// ================================
// 1) IMPORTE firmado
// ================================
// Captura lo que esté justo antes de "EUR"
// Ejemplos válidos: -18, -18.0, -18.00, 18,5, 31.99
let importe_signed = 0;
const m = text.match(/(-?\d+(?:[.,]\d+)?)\s*EUR/i);
if (m) {
  importe_signed = parseFloat(m[1].replace(",", "."));
}

// Total absoluto (para hojas)
const total = Math.abs(importe_signed);

// ================================
// 2) ESTABLECIMIENTO
// ================================
let establecimiento = "";

// Caso típico: "por parte de X con la tarjeta"
let mm = text.match(/por parte de (.+?) con la tarjeta/i);

// Fallback: "en X."
if (!mm) mm = text.match(/\ben\s+(.+?)\./i);

if (mm) establecimiento = mm[1].toUpperCase().trim();

// Caso especial: "TU CUENTA ACABADA EN 9089" => NO SE
if (/TU CUENTA ACABADA EN\s+\d{4}/i.test(textU)) {
  establecimiento = "NO SE";
}

establecimiento = cleanForSheets(establecimiento);

// ================================
// 3) FECHA
// ================================
const fechaRaw = $json.internalDate;
const fecha = fechaRaw ? new Date(Number(fechaRaw)) : new Date();

const fechaISO = `${fecha.getFullYear()}-${pad(fecha.getMonth() + 1)}-${pad(fecha.getDate())}`;
const fechaFull = `${fechaISO} ${pad(fecha.getHours())}:${pad(fecha.getMinutes())}:${pad(fecha.getSeconds())}`;

// ================================
// 4) MOVIMIENTO (LÓGICA DEFINITIVA)
// ================================
// REGLAS:
// 1) INVERSION si contiene "TRADE REPUBLIC"
// 2) INGRESO si |importe| >= 1000 (y no es inversión)
// 3) TODO lo demás es GASTO
//    - RETENCIÓN siempre es GASTO
//    - Da igual signo del importe

let movimiento = "GASTO";
let motivo_movimiento = "DEFAULT_GASTO";

const importeAbs = Math.abs(importe_signed);

// Prioridad 1: INVERSIÓN
if (textU.includes("TRADE REPUBLIC")) {
  movimiento = "INVERSION";
  motivo_movimiento = "KW_TRADE_REPUBLIC";

// Prioridad 2: INGRESO por umbral
} else if (importeAbs >= 1000) {
  movimiento = "INGRESO";
  motivo_movimiento = "IMPORTE_MAYOR_IGUAL_1000";

// Prioridad 3: GASTO (fallback)
} else {
  movimiento = "GASTO";
  motivo_movimiento = (textU.includes("RETENCION") || textU.includes("RETENCIÓN"))
    ? "RETENCION"
    : "DEFAULT_GASTO";
}

// Normalización final (para Switch en n8n)
movimiento = movimiento
  .toString()
  .normalize("NFKD")
  .replace(/[\u200B-\u200D\uFEFF]/g, "")
  .trim()
  .toUpperCase();

// ================================
// 5) OUTPUT
// ================================
return [{
  ...$json,
  establecimiento,
  importe_signed,   // con signo original
  total,            // siempre positivo
  fechaISO,
  fechaFull,
  movimiento,
  motivo_movimiento // útil para debug
}];

// ================================
// 0) Texto del correo (snippet)
// ================================
const text = ($json.snippet || "").toString();
const textU = text.toUpperCase();

// ================================
// Helpers
// ================================
function cleanForSheets(value) {
  let s = (value ?? "").toString()
    .normalize("NFKD")
    .replace(/[\u200B-\u200D\uFEFF]/g, "")
    .trim();

  s = s.replace(/^=\s*/g, "");
  if (!s) s = "NO SE";
  return s;
}

const contiene = (arr, haystack) => arr.some(p => haystack.includes(p));
const pad = (n) => String(n).padStart(2, "0");

// ================================
// 1) IMPORTE
// ================================
let importe_signed = 0;
const m = text.match(/(-?\d+(?:[.,]\d+)?)\s*EUR/i);
if (m) importe_signed = parseFloat(m[1].replace(",", "."));
const total = Math.abs(importe_signed);

// ================================
// 2) ESTABLECIMIENTO
// ================================
let establecimiento = "";
let match = text.match(/por parte de (.+?) con la tarjeta/i);
if (!match) match = text.match(/\ben\s+(.+?)\./i);
if (match) establecimiento = match[1].toUpperCase().trim();

if (/TU CUENTA ACABADA EN\s+\d{4}/i.test(textU)) {
  establecimiento = "NO SE";
}

establecimiento = cleanForSheets(establecimiento);
let est = establecimiento.toUpperCase();

// ================================
// 3) FECHA
// ================================
const fechaRaw = $json.internalDate;
const fecha = fechaRaw ? new Date(Number(fechaRaw)) : new Date();
const hora = fecha.getHours();

const fechaISO = `${fecha.getFullYear()}-${pad(fecha.getMonth() + 1)}-${pad(fecha.getDate())}`;
const fechaFull = `${fechaISO} ${pad(fecha.getHours())}:${pad(fecha.getMinutes())}:${pad(fecha.getSeconds())}`;

// ================================
// 4) Día / Finde
// ================================
const diaSemana = fecha.getDay();
const esViernes = diaSemana === 5;
const esSabado  = diaSemana === 6;
const esDomingo = diaSemana === 0;
const esFindeOviernes = esViernes || esSabado || esDomingo;

// ================================
// 5) Palabras clave
// ================================
const palabrasOcio = [" BAR ", "BAR-", "PUB", "DISCO", "CLUB", "COPAS"];
const palabrasComida = [
  "RESTAURANTE", "CAFETERIA", "CAFETERÍA", "BURGER",
  "PIZZA", "MCDONALD", "KFC", "TACO BELL"
];
const palabrasDeporte = [
  "WELLHUB", "WELLHUB EU", // 👈 añadido aquí también por seguridad
  "GYM", "GIMNASIO", "FITNESS", "CROSSFIT", "BASIC-FIT",
  "MCFIT", "DECATHLON", "NIKE", "ADIDAS", "INTERSPORT", "SPORT"
];

// ================================
// 6) CLASIFICACIÓN (PRIORIDADES NUEVAS)
// ================================
let categoria = "NO_CLASIFICADO";

/**
 * PRIORIDAD 1: MENSUAL (por palabras / casos específicos)
 * (Esto es lo primero que se evalúa)
 */
if (Math.abs(importe_signed + 0.99) < 0.001) {
  establecimiento = "APPLE";
  est = "APPLE";
  categoria = "MENSUAL";

} else if (est.includes("LINKEDIN")) {
  categoria = "MENSUAL";

} else if (est.includes("CHATGPT") || est.includes("OPENAI")) {
  categoria = "MENSUAL";

} else if (est.includes("SPOTIFY")) {
  categoria = "MENSUAL";

} else if (est.includes("METRO DE MADRID")) {
  categoria = "MENSUAL";
}

/**
 * PRIORIDAD 2: OCIO (días/horas + reglas)
 */
else if (est.includes("CAFETERIA LIDER") || est.includes("CAFETERÍA LIDER")) {
  categoria = "OCIO";

} else if (esFindeOviernes && hora >= 20) {
  categoria = "OCIO";

} else if (hora >= 23 || hora < 6) {
  categoria = "OCIO";

} else if (est.includes("ESTANCO")) {
  categoria = "OCIO";

} else if (est.includes("BOLT") || est.includes("TAXI")) {
  categoria = "OCIO";

} else if (est.includes("MERCADONA") && esViernes && hora >= 14) {
  categoria = "OCIO";

} else if (contiene(palabrasOcio, est)) {
  categoria = "OCIO";
}

/**
 * PRIORIDAD 3: COMIDA (por palabras)
 */
else if (contiene(palabrasComida, est)) {
  categoria = "COMIDA";
}

/**
 * PRIORIDAD 4: DEPORTE (por palabras)
 * (incluye WELLHUB EU)
 */
else if (contiene(palabrasDeporte, est) || est.includes("WELLHUB")) {
  categoria = "DEPORTE";
}

/**
 * PRIORIDAD 5: fallback final
 */
else {
  categoria = "NO_CLASIFICADO";
}

// Re-limpieza por si alguna regla cambió el texto
establecimiento = cleanForSheets(establecimiento);

// ================================
// 7) OUTPUT
// ================================
return [{
  ...$json,
  establecimiento,
  categoria,
  fechaISO,
  fechaFull,
  hora,
  esViernes,
  esSabado,
  esDomingo,
  importe_signed,
  total,
}];

// Extrae el JSON desde la estructura del nodo "Message a model"
try {
  // 1. Navegamos hasta el texto con el JSON
  const text = $json.output[0].content[0].text;

  // 2. Intentamos parsearlo
  const parsed = JSON.parse(text);

  // 3. Devolvemos el objeto ya fusionado con el original
  return [{ ...$json, ...parsed }];
} catch (error) {
  // Si algo falla, devolvemos una salida de fallback
  return [{
    ...$json,
    categoria_secundaria: "NO_CLASIFICADO",
    parse_error: error.message
  }];
}
